"use strict";

const mysql = require('mysql2');
const { performance } = require('perf_hooks');

// Create a connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'myapp',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

// Promisify the pool query method
const promisePool = pool.promise();

/**
 * Get a user by ID
 * @param {number} id - The user ID
 * @returns {Promise<Object>} The user object
 */
async function getUserById(id) {
  const query = 'SELECT id, name, email, created_at FROM users WHERE id = ?';
  const startTime = performance.now();

  try {
    const [rows] = await promisePool.execute(query, [id]);
    const endTime = performance.now();
    console.log(`Query getUserById(${id}) executed in ${(endTime - startTime).toFixed(2)}ms`);

    return rows[0] || null;
  } catch (error) {
    const endTime = performance.now();
    console.error(`Query getUserById(${id}) failed after ${(endTime - startTime).toFixed(2)}ms:`, error.message);
    throw error;
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Maximum number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Promise<Array>} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const query = 'SELECT id, name, email, created_at FROM users LIMIT ? OFFSET ?';
  const startTime = performance.now();

  try {
    const [rows] = await promisePool.execute(query, [limit, offset]);
    const endTime = performance.now();
    console.log(`Query getAllUsers(limit=${limit}, offset=${offset}) executed in ${(endTime - startTime).toFixed(2)}ms`);

    return rows;
  } catch (error) {
    const endTime = performance.now();
    console.error(`Query getAllUsers(limit=${limit}, offset=${offset}) failed after ${(endTime - startTime).toFixed(2)}ms:`, error.message);
    throw error;
  }
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum number of results
 * @param {number} offset - Number of results to skip
 * @returns {Promise<Array>} Array of user objects
 */
async function searchUsers(searchQuery, limit = 10, offset = 0) {
  const sql = 'SELECT id, name, email, created_at FROM users WHERE name LIKE ? OR email LIKE ? LIMIT ? OFFSET ?';
  const searchParam = `%${searchQuery}%`;
  const startTime = performance.now();

  try {
    const [rows] = await promisePool.execute(sql, [searchParam, searchParam, limit, offset]);
    const endTime = performance.now();
    console.log(`Query searchUsers(query="${searchQuery}", limit=${limit}, offset=${offset}) executed in ${(endTime - startTime).toFixed(2)}ms`);

    return rows;
  } catch (error) {
    const endTime = performance.now();
    console.error(`Query searchUsers(query="${searchQuery}", limit=${limit}, offset=${offset}) failed after ${(endTime - startTime).toFixed(2)}ms:`, error.message);
    throw error;
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
};

