const mysql = require('mysql2/promise');

// Create connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'appdb',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
});

/**
 * Get user by ID with parameterized query
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
async function getUserById(id) {
  const start = Date.now();
  try {
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users WHERE id = ? LIMIT 1',
      [id]
    );
    const duration = Date.now() - start;
    console.log(`Query getUserById(${id}) executed in ${duration}ms`);

    return rows.length > 0 ? rows[0] : null;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query getUserById(${id}) failed after ${duration}ms:`, error.message);
    throw error;
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users per page
 * @param {number} offset - Offset for pagination
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const start = Date.now();
  try {
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users LIMIT ? OFFSET ?',
      [parseInt(limit), parseInt(offset)]
    );
    const duration = Date.now() - start;
    console.log(`Query getAllUsers(limit=${limit}, offset=${offset}) executed in ${duration}ms`);
    return rows;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query getAllUsers(limit=${limit}, offset=${offset}) failed after ${duration}ms:`, error.message);
    throw error;
  }
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum results to return
 * @returns {Array} Array of matching user objects
 */
async function searchUsers(query, limit = 10) {
  const start = Date.now();

  // Input validation and sanitization
  if (!query || typeof query !== 'string') {
    const duration = Date.now() - start;
    console.log(`Query searchUsers empty or invalid query in ${duration}ms`);
    return [];
  }

  // Sanitize input - remove any potential SQL keywords
  // Note: The parameterized query provides primary protection
  const sanitizedQuery = `%${query.trim().replace(/[%_]/g, '')}%`;

  try {
    const [rows] = await pool.execute(
      `SELECT id, name, email 
       FROM users 
       WHERE name LIKE ? OR email LIKE ? 
       LIMIT ?`,
      [sanitizedQuery, sanitizedQuery, parseInt(limit)]
    );

    const duration = Date.now() - start;
    console.log(`Query searchUsers('${query}', limit=${limit}) executed in ${duration}ms`);
    return rows;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query searchUsers('${query}', limit=${limit}) failed after ${duration}ms:`, error.message);
    throw error;
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
};

