// queries.js - Database query functions with connection pooling and timing

const mysql = require('mysql2/promise');
const poolConfig = {
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'testdb',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
};

const pool = mysql.createPool(poolConfig);

// Utility to log query execution time
const timedQuery = async (queryText, params = []) => {
  const start = Date.now();
  try {
    const [results] = await pool.execute(queryText, params);
    const duration = Date.now() - start;
    console.log(`Query executed in ${duration}ms: ${queryText}`);
    return results;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query failed after ${duration}ms: ${queryText}`, error);
    throw error;
  }
};

// Query Functions

/**
 * Get a user by their ID
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
const getUserById = async (id) => {
  const user = await timedQuery('SELECT id, name, email FROM users WHERE id = ?', [id]);
  return user[0] || null;
};

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Array} Array of user objects
 */
const getAllUsers = async (limit = 10, offset = 0) => {
  // Ensure limit and offset are integers to prevent injection
  const parsedLimit = Math.abs(parseInt(limit, 10));
  const parsedOffset = Math.abs(parseInt(offset, 10));

  return timedQuery(
    'SELECT id, name, email FROM users LIMIT ? OFFSET ?', 
    [parsedLimit, parsedOffset]
  );
};

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @returns {Array} Array of matching user objects
 */
const searchUsers = async (query) => {
  if (typeof query !== 'string' || query.trim().length === 0) {
    return [];
  }

  // Use LIKE with escaped wildcards to prevent injection
  const safeQuery = `%${query.replace(/[%_\\]/g, '\\$&')}%`;
  return timedQuery(
    'SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ?', 
    [safeQuery, safeQuery]
  );
};

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
};

