// Database query functions with connection pooling and timing

const mysql = require('mysql2/promise');

// Connection pool configuration
class Database {
  constructor() {
    this.pool = mysql.createPool({
      host: process.env.DB_HOST || 'localhost',
      user: process.env.DB_USER || 'root',
      password: process.env.DB_PASSWORD || '',
      database: process.env.DB_NAME || 'test',
      waitForConnections: true,
      connectionLimit: 10,
      queueLimit: 0,
      enableKeepAlive: true,
      keepAliveInitialDelay: 0
    });
  }

  async query(sql, params = []) {
    const start = Date.now();
    try {
      const [results] = await this.pool.execute(sql, params);
      const duration = Date.now() - start;
      console.log(`Query executed in ${duration}ms: ${sql} | Params: ${JSON.stringify(params)}`);
      return results;
    } catch (error) {
      const duration = Date.now() - start;
      console.error(`Query failed after ${duration}ms: ${sql} | Params: ${JSON.stringify(params)}`);
      throw error;
    }
  }
}

const db = new Database();

/**
 * Get a user by their ID
 * @param {number} id - The user ID
 * @returns {Object|null} User object or null if not found
 */
async function getUserById(id) {
  if (!Number.isInteger(parseInt(id)) || parseInt(id) <= 0) {
    throw new Error('Invalid user ID');
  }

  const result = await db.query(
    'SELECT id, name, email FROM users WHERE id = ?', 
    [parseInt(id)]
  );

  return result[0] || null;
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const parsedLimit = Math.min(Math.abs(parseInt(limit)) || 10, 100);
  const parsedOffset = Math.abs(parseInt(offset)) || 0;

  return await db.query(
    'SELECT id, name, email FROM users LIMIT ? OFFSET ?', 
    [parsedLimit, parsedOffset]
  );
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @returns {Array} Array of matching user objects
 */
async function searchUsers(query) {
  if (!query || typeof query !== 'string') {
    return [];
  }

  // Sanitize input and prepare for SQL LIKE pattern
  const searchTerm = `%${query.trim().replace(/[%_\\]/g, '\$&')}%`;

  return await db.query(
    'SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ?', 
    [searchTerm, searchTerm]
  );
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
};

