// queries.js - Database query functions with connection pooling and logging

const mysql = require('mysql2/promise');
const config = require('./config/database');

// Create connection pool
const pool = mysql.createPool({
  host: config.host,
  user: config.user,
  password: config.password,
  database: config.database,
  port: config.port,
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Execute a query with timing logs and error handling
 * @param {string} sql - SQL query string
 * @param {Array} params - Query parameters
 * @returns {Object} Query result
 */
async function executeQuery(sql, params = []) {
  const startTime = Date.now();

  try {
    console.log(`Executing query: ${sql} | Parameters: ${JSON.stringify(params)}`);

    const [results] = await pool.execute(sql, params);

    const duration = Date.now() - startTime;
    console.log(`Query executed successfully in ${duration}ms`);

    return results;
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`Query failed after ${duration}ms:`, error.message);
    throw error;
  }
}

/**
 * Get a user by ID
 * @param {number} id - User ID
 * @returns {Object} User data
 */
async function getUserById(id) {
  // Validate input type and range
  const userId = parseInt(id, 10);
  if (isNaN(userId) || userId <= 0) {
    throw new Error('Invalid user ID');
  }

  const sql = 'SELECT id, name, email FROM users WHERE id = ?';
  const results = await executeQuery(sql, [userId]);

  return results[0] || null;
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users per page
 * @param {number} offset - Starting position
 * @returns {Array} List of users
 */
async function getAllUsers(limit = 10, offset = 0) {
  // Validate and sanitize parameters
  const safeLimit = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 100);
  const safeOffset = Math.max(parseInt(offset, 10) || 0, 0);

  const sql = 'SELECT id, name, email FROM users LIMIT ? OFFSET ?';
  return await executeQuery(sql, [safeLimit, safeOffset]);
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @returns {Array} Matching users
 */
async function searchUsers(query) {
  // Validate and sanitize search query
  if (!query || typeof query !== 'string') {
    throw new Error('Search query is required and must be a string');
  }

  // Trim and limit query length
  const cleanQuery = query.trim().substring(0, 255);

  if (cleanQuery.length === 0) {
    throw new Error('Search query cannot be empty');
  }

  // Use parameterized query with LIKE for search
  // The database driver handles proper escaping
  const sql = `SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ?`;
  const searchPattern = `%${cleanQuery}%`;

  return await executeQuery(sql, [searchPattern, searchPattern]);
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for graceful shutdown if needed
  pool
};

