const { Pool } = require('pg');

// Create a connection pool
const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgresql://localhost:5432/myapp',
  max: 20, // maximum number of clients in the pool
  idleTimeoutMillis: 30000, // close idle clients after 30 seconds
  connectionTimeoutMillis: 2000, // return an error after 2 seconds if connection could not be established
});

/**
 * Get a single user by ID
 * @param {number} id - User ID
 * @returns {Promise<Object|null>} User object or null if not found
 */
async function getUserById(id) {
  const start = Date.now();
  try {
    const client = await pool.connect();
    try {
      const result = await client.query('SELECT id, name, email FROM users WHERE id = $1', [id]);
      return result.rows[0] || null;
    } finally {
      client.release();
    }
  } catch (error) {
    console.error('Error in getUserById:', error);
    throw error;
  } finally {
    const duration = Date.now() - start;
    console.log(`getUserById(${id}) executed in ${duration}ms`);
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Promise<Array>} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const start = Date.now();
  try {
    const client = await pool.connect();
    try {
      const result = await client.query(
        'SELECT id, name, email FROM users ORDER BY id LIMIT $1 OFFSET $2',
        [limit, offset]
      );
      return result.rows;
    } finally {
      client.release();
    }
  } catch (error) {
    console.error('Error in getAllUsers:', error);
    throw error;
  } finally {
    const duration = Date.now() - start;
    console.log(`getAllUsers(limit=${limit}, offset=${offset}) executed in ${duration}ms`);
  }
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum number of results
 * @returns {Promise<Array>} Array of matching user objects
 */
async function searchUsers(query, limit = 10) {
  const start = Date.now();
  try {
    // Validate and sanitize input
    if (!query || typeof query !== 'string') {
      return [];
    }

    const searchTerm = query.trim();
    if (searchTerm.length === 0) {
      return [];
    }

    const client = await pool.connect();
    try {
      // Use parameterized query with ILIKE for case-insensitive search
      // and % wildcards for partial matching
      const result = await client.query(
        'SELECT id, name, email FROM users WHERE name ILIKE $1 OR email ILIKE $1 ORDER BY name LIMIT $2',
        [`%${searchTerm}%`, limit]
      );
      return result.rows;
    } finally {
      client.release();
    }
  } catch (error) {
    console.error('Error in searchUsers:', error);
    throw error;
  } finally {
    const duration = Date.now() - start;
    console.log(`searchUsers(query='${query}', limit=${limit}) executed in ${duration}ms`);
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for health checks or other uses
  pool,
};

