// queries.js - Database query functions
const { Pool } = require('pg');

// Connection pool configuration
class QueryManager {
  constructor() {
    this.pool = new Pool({
      user: process.env.DB_USER || 'postgres',
      host: process.env.DB_HOST || 'localhost',
      database: process.env.DB_NAME || 'appdb',
      password: process.env.DB_PASSWORD || 'password',
      port: process.env.DB_PORT || 5432,
      max: 20, // maximum number of clients in the pool
      idleTimeoutMillis: 30000, // close idle clients after 30 seconds
      connectionTimeoutMillis: 2000, // return an error after 2 seconds if connection could not be established
    });

    // Log when pool is created
    console.log('Database connection pool created');
  }

  // Get user by ID with query timing and injection prevention
  async getUserById(id) {
    const start = Date.now();
    const query = {
      text: 'SELECT id, name, email FROM users WHERE id = $1',
      values: [id],
    };

    try {
      const res = await this.pool.query(query);
      const duration = Date.now() - start;
      console.log(`getUserById(${id}) took ${duration}ms`);
      return res.rows[0] || null;
    } catch (err) {
      const duration = Date.now() - start;
      console.error(`getUserById(${id}) failed after ${duration}ms`, err.message);
      throw err;
    }
  }

  // Get all users with pagination
  async getAllUsers(limit = 10, offset = 0) {
    const start = Date.now();
    const query = {
      text: 'SELECT id, name, email FROM users LIMIT $1 OFFSET $2',
      values: [limit, offset],
    };

    try {
      const res = await this.pool.query(query);
      const duration = Date.now() - start;
      console.log(`getAllUsers(limit=${limit}, offset=${offset}) took ${duration}ms`);
      return res.rows;
    } catch (err) {
      const duration = Date.now() - start;
      console.error(`getAllUsers(limit=${limit}, offset=${offset}) failed after ${duration}ms`, err.message);
      throw err;
    }
  }

  // Search users by name or email
  async searchUsers(searchTerm, limit = 10, offset = 0) {
    const start = Date.now();
    // SQL injection prevention: use parameterized queries with LIKE
    // The wildcard % is in the parameter, not in the SQL string
    const query = {
      text: `SELECT id, name, email 
             FROM users 
             WHERE name ILIKE $1 OR email ILIKE $1 
             LIMIT $2 OFFSET $3`,
      values: [`%${searchTerm}%`, limit, offset],
    };

    try {
      const res = await this.pool.query(query);
      const duration = Date.now() - start;
      console.log(`searchUsers("${searchTerm}") took ${duration}ms`);
      return res.rows;
    } catch (err) {
      const duration = Date.now() - start;
      console.error(`searchUsers("${searchTerm}") failed after ${duration}ms`, err.message);
      throw err;
    }
  }

  // Graceful shutdown
  async close() {
    await this.pool.end();
    console.log('Database connection pool closed');
  }
}

module.exports = new QueryManager();

