const mysql = require('mysql2/promise');

// Create connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'appdb',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Get a single user by ID
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
async function getUserById(id) {
  const start = Date.now();
  let conn;
  try {
    conn = await pool.getConnection();
    const [rows] = await conn.execute(
      'SELECT id, name, email FROM users WHERE id = ?',
      [id]
    );

    const queryTime = Date.now() - start;
    console.log(`getUserById(${id}) executed in ${queryTime}ms`);

    return rows[0] || null;
  } catch (error) {
    const queryTime = Date.now() - start;
    console.error(`getUserById(${id}) failed after ${queryTime}ms:`, error.message);
    throw error;
  } finally {
    if (conn) conn.release();
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Starting position
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const start = Date.now();
  let conn;
  try {
    conn = await pool.getConnection();
    const [rows] = await conn.execute(
      'SELECT id, name, email FROM users LIMIT ? OFFSET ?',
      [limit, offset]
    );

    const queryTime = Date.now() - start;
    console.log(`getAllUsers(limit=${limit}, offset=${offset}) executed in ${queryTime}ms`);

    return rows;
  } catch (error) {
    const queryTime = Date.now() - start;
    console.error(`getAllUsers(limit=${limit}, offset=${offset}) failed after ${queryTime}ms:`, error.message);
    throw error;
  } finally {
    if (conn) conn.release();
  }
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum number of results
 * @returns {Array} Array of user objects matching the search
 */
async function searchUsers(query, limit = 10) {
  const start = Date.now();
  let conn;
  try {
    conn = await pool.getConnection();

    // Use LIKE with wildcards for partial matching, parameterized to prevent SQL injection
    const searchPattern = `%${query}%`;
    const [rows] = await conn.execute(
      'SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ? LIMIT ?',
      [searchPattern, searchPattern, limit]
    );

    const queryTime = Date.now() - start;
    console.log(`searchUsers(query='${query}', limit=${limit}) executed in ${queryTime}ms`);

    return rows;
  } catch (error) {
    const queryTime = Date.now() - start;
    console.error(`searchUsers(query='${query}', limit=${limit}) failed after ${queryTime}ms:`, error.message);
    throw error;
  } finally {
    if (conn) conn.release();
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
};

