const { Pool } = require('pg');

// Create connection pool using DATABASE_URL from environment
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20, // maximum number of clients in the pool
  min: 2,  // minimum number of clients in the pool
  idleTimeoutMillis: 30000, // how long a client is allowed to remain idle before being closed
  connectionTimeoutMillis: 2000, // how long to wait before timing out when connecting a new client
});

// Query wrapper with timing logging
async function queryWithTiming(text, params = []) {
  const start = Date.now();
  try {
    const res = await pool.query(text, params);
    const duration = Date.now() - start;
    console.log('Executed query:', { text, rowCount: res.rowCount, duration: `${duration}ms` });
    return res;
  } catch (err) {
    const duration = Date.now() - start;
    console.error('Query failed:', { text, duration: `${duration}ms`, error: err.message });
    throw err;
  }
}

// Get a single user by ID
// Uses parameterized query to prevent SQL injection
async function getUserById(id) {
  const query = {
    text: 'SELECT id, name, email FROM users WHERE id = $1',
    values: [id]
  };
  const result = await queryWithTiming(query.text, query.values);
  return result.rows[0] || null;
}

// Get all users with pagination
// Uses parameterized queries for limit and offset to prevent injection
async function getAllUsers(limit = 50, offset = 0) {
  // Enforce reasonable limits
  const maxLimit = 100;
  const safeLimit = Math.min(parseInt(limit, 10) || 50, maxLimit);
  const safeOffset = parseInt(offset, 10) || 0;

  const query = {
    text: 'SELECT id, name, email FROM users ORDER BY id LIMIT $1 OFFSET $2',
    values: [safeLimit, safeOffset]
  };
  const result = await queryWithTiming(query.text, query.values);
  return result.rows;
}

// Search users by name or email
// Uses parameterized query with LIKE pattern
async function searchUsers(searchTerm) {
  if (!searchTerm || typeof searchTerm !== 'string') {
    return [];
  }

  // Sanitize and prepare search term for LIKE query
  const sanitizedTerm = `%${searchTerm.trim().replace(/%/g, '\%').replace(/_/g, '\_')}%`;

  const query = {
    text: `SELECT id, name, email 
           FROM users 
           WHERE name ILIKE $1 OR email ILIKE $1 
           ORDER BY name`,
    values: [sanitizedTerm]
  };
  const result = await queryWithTiming(query.text, query.values);
  return result.rows;
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for health checks or direct access if needed
  pool
};

