});

// Utility function to execute queries with timing and logging
async function executeQuery(sql, params = []) {
  const startTime = Date.now();

  try {
    const [results] = await pool.execute(sql, params);
    const duration = Date.now() - startTime;
    console.log(`Query executed successfully in ${duration}ms: ${sql}`);

    return results;
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`Query failed after ${duration}ms: ${sql}`, error);
    throw error;
  }
}

// Get user by ID with SQL injection prevention through parameterized queries
async function getUserById(id) {
  if (typeof id !== 'number' || id <= 0) {
    throw new Error('Invalid user ID');
  }

  const sql = 'SELECT id, name, email FROM users WHERE id = ?';
  const results = await executeQuery(sql, [id]);

  return results[0] || null;
}

// Get all users with pagination
async function getAllUsers(limit = 10, offset = 0) {
  // Validate and sanitize inputs to prevent malicious values
  const parsedLimit = Math.min(Math.abs(parseInt(limit) || 10), 100); // Max 100 per request
  const parsedOffset = Math.max(0, parseInt(offset) || 0);

  const sql = 'SELECT id, name, email FROM users LIMIT ? OFFSET ?';
  return await executeQuery(sql, [parsedLimit, parsedOffset]);
}

// Search users by name or email with wildcard matching
async function searchUsers(searchQuery) {
  if (!searchQuery || typeof searchQuery !== 'string') {
    throw new Error('Search query is required and must be a string');
  }

  // Sanitize input and add wildcards for partial matching
  const safeQuery = `%${searchQuery.trim().replace(/[%_]/g, '')}%`;
  const sql = 'SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ?';

  return await executeQuery(sql, [safeQuery, safeQuery]);
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for graceful shutdown if needed
  closePool: () => pool.end()
};

