// mock-queries.js - Mock database query functions for testing without real database

// Mock user data
const mockUsers = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
  { id: 3, name: 'Charlie', email: 'charlie@example.com' },
  { id: 4, name: 'Diana', email: 'diana@example.com' }
];

// Simulate query timing
function simulateQueryDelay() {
  return new Promise(resolve => {
    setTimeout(resolve, Math.random() * 100); // Simulate network/database delay
  });
}

// Get user by ID
async function getUserById(id) {
  console.log(`Query: Getting user with id=${id}`);
  await simulateQueryDelay();

  if (typeof id !== 'number' || id <= 0) {
    throw new Error('Invalid user ID');
  }

  return mockUsers.find(user => user.id === id) || null;
}

// Get all users with pagination
async function getAllUsers(limit = 10, offset = 0) {
  console.log(`Query: Getting users with limit=${limit}, offset=${offset}`);
  await simulateQueryDelay();

  // Validate and sanitize inputs
  const parsedLimit = Math.min(Math.abs(parseInt(limit) || 10), 100);
  const parsedOffset = Math.max(0, parseInt(offset) || 0);

  return mockUsers.slice(parsedOffset, parsedOffset + parsedLimit);
}

// Search users by name or email
async function searchUsers(searchQuery) {
  console.log(`Query: Searching users with query=${searchQuery}`);
  await simulateQueryDelay();

  if (!searchQuery || typeof searchQuery !== 'string') {
    throw new Error('Search query is required and must be a string');
  }

  const query = searchQuery.trim().toLowerCase();
  return mockUsers.filter(user => 
    user.name.toLowerCase().includes(query) || 
    user.email.toLowerCase().includes(query)
  );
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
};

